/** The drawing's viewBox: every layer uses it, so the layers line up exactly. */
const VIEW_BOX = "6 4 980 954";
const INK = "#16232B";

function Layer({ className, children }: { className?: string; children: ReactNode }) {
  return (
    <svg
      className={className}
      viewBox={VIEW_BOX}
      aria-hidden="true"
      focusable="false"
      pointerEvents="none"
    >
      {children}
    </svg>
  );
}

